#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using i128 = __int128_t;

const int MOD = 998244353;

string to_string(i128 x) {
    if (x == 0) return "0";
    string s;
    bool neg = x < 0;
    if (neg) x = -x;
    while (x > 0) {
        s += '0' + (x % 10);
        x /= 10;
    }
    if (neg) s += '-';
    reverse(s.begin(), s.end());
    return s;
}

void solve_subsets(const vector<int>& v, int b, i128& res) {
    int n = v.size();
    vector<int> left, right;

    function<void(int, int)> f = [&](int i, int cur) {
        if (i == n/2) {
            left.push_back((cur + b) % MOD);
            return;
        }
        f(i+1, cur);
        f(i+1, (cur + v[i]) % MOD);
    };

    f(0, 0);

    function<void(int, int)> g = [&](int i, int cur) {
        if (i == n) {
            right.push_back(cur);
            return;
        }
        g(i+1, cur);
        g(i+1, (cur + v[i]) % MOD);
    };

    g(n/2, 0);

    sort(left.begin(), left.end());
    sort(right.begin(), right.end());

    ll sumR = 0;
    for (int x : right) sumR = (sumR + x) % MOD;

    int j = right.size() - 1;
    for (int x : left) {
        while (j >= 0 && x + right[j] >= MOD) --j;
        res += (ll)x * right.size() + sumR - (ll)(right.size() - 1 - j) * MOD;
    }
}

ll p10[17];

ll count_with(const string& pre, ll max_n, const string& nstr) {
    ll val = 0;
    for (char c : pre) val = val * 10 + (c - '0');

    ll cnt = 0;
    int plen = pre.size();
    int nlen = nstr.size();

    for (int len = plen; len <= nlen; ++len) {
        if (len < nlen) {
            cnt += p10[len - plen];
        } else {
            if (pre < nstr) {
                cnt += p10[len - plen];
            } else if (pre == nstr) {
                cnt += max_n - val * p10[nlen - plen] + 1;
            }
        }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    string ns;
    if (n == 0) ns = "0";
    else {
        ll t = n;
        while (t) {
            ns += '0' + (t % 10);
            t /= 10;
        }
        reverse(ns.begin(), ns.end());
    }

    p10[0] = 1;
    for (int i = 1; i < 17; ++i) p10[i] = p10[i-1] * 10;

    i128 total = 0;

    for (int len = 1; len <= (int)ns.size(); ++len) {
        for (int diff = 0; diff < min(len, (int)ns.size()); ++diff) {
            string cur;
            ll val = 0;

            for (int i = 0; i < diff; ++i) {
                cur += ns[i];
                val = val * 10 + (ns[i] - '0');
            }

            for (int d = 0; d <= 9; ++d) {
                if (diff == 0 && d == 0) continue;
                if (diff < (int)ns.size() && d == ns[diff] - '0') continue;
                if (len == (int)ns.size() && d > ns[diff] - '0') continue;

                string new_cur = cur + char('0' + d);
                ll new_val = val * 10 + d;

                ll base = 0;
                string tmp;

                for (int i = 0; i < (int)new_cur.size(); ++i) {
                    char start = (i == 0) ? '1' : '0';
                    for (char c = start; c < new_cur[i]; ++c) {
                        base += count_with(tmp + c, n, ns);
                    }
                    tmp += new_cur[i];
                }
                base += (int)new_cur.size() - 1;

                vector<int> vars;
                tmp = new_cur;
                for (int i = new_cur.size(); i < len; ++i) {
                    int cnt = count_with(tmp + '0', n, ns) % MOD;
                    vars.push_back(cnt);
                    tmp += '0';
                }

                base += 1;
                base -= new_val * p10[len - new_cur.size()];

                for (int i = 0; i < (int)vars.size(); ++i) {
                    vars[(int)vars.size() - 1 - i] -= p10[i] % MOD;
                }

                int b = base % MOD;
                if (b < 0) b += MOD;

                for (int& v : vars) {
                    v %= MOD;
                    if (v < 0) v += MOD;
                }

                solve_subsets(vars, b, total);
            }
        }
    }

    // Handle exact prefixes
    string prefix;
    ll val = 0;
    for (int len = 1; len <= (int)ns.size(); ++len) {
        prefix += ns[len-1];
        val = val * 10 + (ns[len-1] - '0');

        ll cnt = 1;
        string tmp;
        for (int i = 0; i < (int)prefix.size(); ++i) {
            char start = (i == 0) ? '1' : '0';
            for (char c = start; c < prefix[i]; ++c) {
                cnt += count_with(tmp + c, n, ns);
            }
            tmp += prefix[i];
        }
        cnt += (int)prefix.size() - 1;
        cnt -= val;
        cnt %= MOD;
        if (cnt < 0) cnt += MOD;

        total += cnt;
    }

    total %= 1000000007LL;
    cout << to_string(total) << "\n";

    return 0;
}
